public:
    int minimumMoves(string s) {
        int res = 0, run = 0;
        for (char c : s) {
            if (c == 'X') run++;
            else { res += (run + 2) / 3; run = 0; }
        }
        res += (run + 2) / 3;
        return res;
    }
};

